import cs1302.tracer.api.*;
import java.nio.file.*;
import java.util.*;
public class ApiProbe {
 public static void main(String[] args) throws Exception {
   String source = Files.readString(Path.of(args[0]));
   TraceRequest.Builder b = TraceRequest.builder(source).format(TraceFormat.MODERN);
   if (args.length > 1 && args[1].equals("files")) b.limits(TraceLimits.builder().sourceFiles(1).build());
   if (args.length > 1 && args[1].equals("project")) b.breakpoints(List.of("4", "6"));
   System.out.println(Tracer.trace(b.build()).json());
 }
}

