import com.sun.jdi.Bootstrap;
import javax.tools.ToolProvider;
public class HostProbe {
 public static void main(String[] args) {
   System.out.println("java.home=" + System.getProperty("java.home"));
   System.out.println("compiler.module=" + ToolProvider.getSystemJavaCompiler().getClass().getModule().getName());
   var connector = Bootstrap.virtualMachineManager().defaultConnector();
   System.out.println("jdi.module=" + Bootstrap.class.getModule().getName());
   System.out.println("connector.name=" + connector.name());
   System.out.println("connector.home=" + connector.defaultArguments().get("home").value());
 }
}

