import java.net.*;
import java.nio.file.*;
import java.security.*;
public class NonFileSourceProbe {
 public static void main(String[] args) throws Exception {
   URL jar = Path.of(args[0]).toUri().toURL();
   try (URLClassLoader loader = new URLClassLoader(new URL[]{jar}, ClassLoader.getPlatformClassLoader()) {
      @Override protected Class<?> findClass(String name) throws ClassNotFoundException {
        if (!name.equals("cs1302.tracer.internal.guest.GuestHarness")) return super.findClass(name);
        String path = name.replace('.', '/') + ".class";
        try (var input = findResource(path).openStream()) {
          byte[] bytes = input.readAllBytes();
          var source = new CodeSource(URI.create("jar:" + jar + "!/BOOT-INF/lib/tracer.jar").toURL(), (java.security.cert.Certificate[])null);
          return defineClass(name, bytes, 0, bytes.length, new ProtectionDomain(source, null, this, null));
        } catch (Exception e) { throw new ClassNotFoundException(name, e); }
      }
   }) {
      Class<?> request = loader.loadClass("cs1302.tracer.api.TraceRequest");
      Object input = request.getConstructor(String.class).newInstance("public class Main { public static void main(String[] args) {} }");
      Object result = loader.loadClass("cs1302.tracer.api.Tracer").getMethod("trace", request).invoke(null, input);
      System.out.println(result.getClass().getMethod("json").invoke(result));
   }
 }
}

